  // 새로고침하면 다시 처음 속도로 돌아가도 상관없는 값이고, 이거 하나 때문에
  // localStorage 구조를 늘릴 이유가 없다.
  let analysisRunsThisSession = 0;
  let pendingMessageAnalysis = null;
  let typingTimer = null;
  let activeGiftDrag = null;
  let selectedGiftIndex = null;
